refentry.refsect1:
&reftitle.returnvalues;

 При успешном выполнении функция возвращает массив сведений о файле&return.falseforfailure;.
 Подробнее о возвращаемых значениях рассказывает документация к функции stat.

  &reftitle.examples;

   Пример получения информации о файле через SFTP


<?php

$connection = ssh2_connect('shell.example.com', 22);
ssh2_auth_password($connection, 'username', 'password');

$sftp = ssh2_sftp($connection);
$statinfo = ssh2_sftp_stat($sftp, '/path/to/file');

$filesize = $statinfo['size'];
$group = $statinfo['gid'];
$owner = $statinfo['uid'];
$atime = $statinfo['atime'];
$mtime = $statinfo['mtime'];
$mode = $statinfo['mode'];
